<?php
require_once '../includes/role.php'; requireRole('admin'); require_once '../config/database.php'; require_once '../includes/csrf.php';
$error=''; $success='';
$q=trim($_GET['q']??''); $filterStatus=$_GET['status']??'';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();
 $action=$_POST['action']??''; $id=(int)($_POST['id']??0); $name=trim($_POST['name']??''); $description=trim($_POST['description']??''); $price=(float)($_POST['price']??0); $duration=(int)($_POST['duration']??0);
 if($action==='save' && ($name===''||$price<0||$duration<1)) $error='Nama, harga, dan durasi harus valid.';
 elseif($action==='save'){ if($id){$s=$pdo->prepare('UPDATE services SET name=?,description=?,price=?,duration=? WHERE id=?');$s->execute([$name,$description!==''?$description:null,$price,$duration,$id]);$success='Layanan diperbarui.';}else{$s=$pdo->prepare('INSERT INTO services(name,description,price,duration) VALUES(?,?,?,?)');$s->execute([$name,$description!==''?$description:null,$price,$duration]);$success='Layanan ditambahkan.';} }
 elseif($action==='toggle'&&$id){$s=$pdo->prepare("UPDATE services SET status=IF(status='active','inactive','active') WHERE id=?");$s->execute([$id]);$success='Status layanan diperbarui.';}
}
$sql="SELECT * FROM services WHERE 1=1"; $params=[]; if($q!==''){ $sql.=" AND (name LIKE ? OR description LIKE ?)"; $like="%$q%"; $params=[$like,$like]; } if(in_array($filterStatus,['active','inactive'],true)){ $sql.=" AND status=?"; $params[]=$filterStatus; } $sql.=" ORDER BY status DESC,name"; $stmt=$pdo->prepare($sql); $stmt->execute($params); $services=$stmt->fetchAll();
$pageTitle='Data Layanan'; require '../includes/admin_header.php';
?>
<?php if($error): ?><div class="alert"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if($success): ?><div class="success"><?= htmlspecialchars($success) ?></div><?php endif; ?>
<div class="two-column"><section class="panel"><div class="panel-heading"><h2><?= isset($_GET['edit'])?'Edit':'Tambah' ?> Layanan</h2></div>
<?php $edit=null;if(isset($_GET['edit'])){foreach($services as $x){if($x['id']==(int)$_GET['edit']){$edit=$x;break;}}} ?>
<form method="post" class="compact-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= $edit['id']??0 ?>"><label>Nama<input name="name" value="<?= htmlspecialchars($edit['name']??'') ?>" required></label><label>Deskripsi<textarea name="description" rows="4"><?= htmlspecialchars($edit['description']??'') ?></textarea></label><label>Harga<input type="number" min="0" step="0.01" name="price" value="<?= htmlspecialchars($edit['price']??'0') ?>" required></label><label>Durasi (menit)<input type="number" min="1" name="duration" value="<?= htmlspecialchars($edit['duration']??'60') ?>" required></label><button type="submit">Simpan</button><?php if($edit): ?><a href="services.php" class="button secondary">Batal</a><?php endif; ?></form></section>
<section class="panel"><div class="panel-heading"><h2>Daftar Layanan</h2></div><form method="get" class="admin-filter-form"><input type="search" name="q" value="<?= htmlspecialchars($q) ?>" placeholder="Cari nama atau deskripsi layanan..."><select name="status"><option value="">Semua status</option><option value="active" <?= $filterStatus==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= $filterStatus==='inactive'?'selected':'' ?>>Inactive</option></select><button class="small" type="submit">Filter</button><a class="button small secondary" href="services.php">Reset</a></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Layanan</th><th>Harga</th><th>Durasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($services as $s): ?><tr><td><strong><?= htmlspecialchars($s['name']) ?></strong><small><?= htmlspecialchars($s['description']??'') ?></small></td><td>Rp <?= number_format($s['price'],0,',','.') ?></td><td><?= $s['duration'] ?> mnt</td><td><span class="badge badge-<?= $s['status'] ?>"><?= $s['status'] ?></span></td><td><a class="button small secondary" href="services.php?edit=<?= $s['id'] ?>">Edit</a><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= $s['id'] ?>"><button class="small" type="submit"><?= $s['status']==='active'?'Nonaktifkan':'Aktifkan' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div>
<?php require '../includes/admin_footer.php'; ?>
